// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title TokenVesting
 * @notice Linear vesting with cliff periods and beneficiary delegation
 */
contract TokenVesting is ReentrancyGuard {
    using SafeERC20 for IERC20;

    struct VestingSchedule {
        address beneficiary;
        address token;
        uint256 totalAmount;
        uint256 released;
        uint256 startTime;
        uint256 cliffDuration;
        uint256 vestingDuration;
        bool revocable;
        bool revoked;
    }

    mapping(bytes32 => VestingSchedule) public schedules;
    mapping(address => bytes32[]) public beneficiarySchedules;
    mapping(address => uint256) public totalAllocated;
    address public owner;

    event ScheduleCreated(bytes32 indexed scheduleId, address indexed beneficiary);
    event TokensReleased(bytes32 indexed scheduleId, uint256 amount);
    event ScheduleRevoked(bytes32 indexed scheduleId);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    function createSchedule(
        address _beneficiary,
        address _token,
        uint256 _totalAmount,
        uint256 _startTime,
        uint256 _cliffDuration,
        uint256 _vestingDuration
    ) external onlyOwner returns (bytes32) {
        require(_beneficiary != address(0), "Zero address");
        require(_totalAmount > 0, "Zero amount");
        require(_vestingDuration > 0, "Zero duration");
        require(_cliffDuration <= _vestingDuration, "Cliff exceeds vesting");
        require(_startTime <= block.timestamp + 365 days, "Start too far");

        bytes32 scheduleId = keccak256(
            abi.encodePacked(_beneficiary, _token, _totalAmount, block.timestamp)
        );
        require(schedules[scheduleId].totalAmount == 0, "Schedule exists");

        schedules[scheduleId] = VestingSchedule({
            beneficiary: _beneficiary,
            token: _token,
            totalAmount: _totalAmount,
            released: 0,
            startTime: _startTime,
            cliffDuration: _cliffDuration,
            vestingDuration: _vestingDuration,
            revocable: true,
            revoked: false
        });

        beneficiarySchedules[_beneficiary].push(scheduleId);
        totalAllocated[_token] += _totalAmount;

        IERC20(_token).safeTransferFrom(msg.sender, address(this), _totalAmount);

        emit ScheduleCreated(scheduleId, _beneficiary);
        return scheduleId;
    }

    /**
     * @notice Computes the vested amount for a schedule
     * @dev Uses linear vesting after cliff
     */
    function computeVestedAmount(bytes32 _scheduleId) public view returns (uint256) {
        VestingSchedule storage schedule = schedules[_scheduleId];

        if (schedule.revoked) {
            return schedule.released;
        }

        uint256 currentTime = block.timestamp;
        uint256 cliffEnd = schedule.startTime + schedule.cliffDuration;

        if (currentTime < cliffEnd) {
            return 0;
        }

        uint256 elapsedSinceStart = currentTime - schedule.startTime;

        if (elapsedSinceStart >= schedule.vestingDuration) {
            return schedule.totalAmount;
        }

        // Linear vesting calculation
        uint256 vestedAmount = (schedule.totalAmount * elapsedSinceStart) / schedule.vestingDuration;
        return vestedAmount;
    }

    /**
     * @notice Release vested tokens for multiple schedules
     * @dev Batch release with accumulated computation
     */
    function batchRelease(bytes32[] calldata _scheduleIds) external nonReentrant {
        require(_scheduleIds.length <= 20, "Too many schedules");
        for (uint256 i = 0; i < _scheduleIds.length; i++) {
            _releaseFor(_scheduleIds[i]);
        }
    }

    function _releaseFor(bytes32 _scheduleId) internal {
        VestingSchedule storage schedule = schedules[_scheduleId];
        require(msg.sender == schedule.beneficiary, "Not beneficiary");
        require(!schedule.revoked, "Schedule revoked");

        uint256 vested = computeVestedAmount(_scheduleId);
        uint256 releasable = vested - schedule.released;
        require(releasable > 0, "Nothing to release");

        schedule.released += releasable;
        totalAllocated[schedule.token] -= releasable;

        IERC20(schedule.token).safeTransfer(schedule.beneficiary, releasable);
        emit TokensReleased(_scheduleId, releasable);
    }

    /**
     * @notice Revoke a schedule and return unvested tokens to owner
     */
    function revoke(bytes32 _scheduleId) external onlyOwner {
        VestingSchedule storage schedule = schedules[_scheduleId];
        require(schedule.revocable, "Not revocable");
        require(!schedule.revoked, "Already revoked");

        uint256 vested = computeVestedAmount(_scheduleId);
        uint256 unvested = schedule.totalAmount - vested;

        schedule.revoked = true;
        totalAllocated[schedule.token] -= unvested;

        if (unvested > 0) {
            IERC20(schedule.token).safeTransfer(owner, unvested);
        }

        emit ScheduleRevoked(_scheduleId);
    }

    /**
     * @notice Accelerate vesting for a beneficiary (e.g., on acquisition)
     * @dev Sets vesting duration to elapsed time, making tokens vest faster
     */
    function accelerateVesting(bytes32 _scheduleId, uint256 _newEndTime) external onlyOwner {
        VestingSchedule storage schedule = schedules[_scheduleId];
        require(!schedule.revoked, "Schedule revoked");
        require(_newEndTime > schedule.startTime, "Invalid end time");
        require(_newEndTime >= block.timestamp, "End time in past");

        // New duration must be shorter (acceleration only)
        uint256 newDuration = _newEndTime - schedule.startTime;
        require(newDuration <= schedule.vestingDuration, "Cannot extend vesting");
        schedule.vestingDuration = newDuration;

        // Cliff is removed on acceleration if it hasn't passed
        if (block.timestamp < schedule.startTime + schedule.cliffDuration) {
            schedule.cliffDuration = 0;
        }
    }
}
